// Des: Spot Facebook challenges and logouts so the agent stops or waits
// Flo: lowercase url, page text, dialog text > match url parts > strong phrases on page text > weak phrases only inside dialogs > Halt kind > class (needs you or unsafe)
// I/O: url + page text + dialog/alert text (caller) > optional Halt kind, its Class (never bypassed, never retried blindly)
// ===================================================================
const std = @import("std"); const fld = @import("ut-text-fold.zig");
const CF = .{ .scan = 6000 };
pub const Halt = enum { checkpoint, captcha, twofa, warning, blocked, ratelimit, logout, overlay };
pub const Class = enum { needs, unsafe };
const Rule = struct { kind: Halt, weak: bool, urlz: []const []const u8, text: []const []const u8 };
const RULES = [_]Rule{ .{ .kind = .checkpoint, .weak = false, .urlz = &.{ "/checkpoint", "/confirmemail", "/recover", "/disabled" }, .text = &.{ "confirm your identity", "we suspended your account", "your account has been disabled", "your account has been locked", "xác nhận danh tính", "tài khoản của bạn đã bị khóa", "tài khoản của bạn đã bị vô hiệu hóa" } }, .{ .kind = .captcha, .weak = false, .urlz = &.{ "/captcha", "/recaptcha" }, .text = &.{ "security check", "type the characters", "i'm not a robot", "kiểm tra bảo mật", "nhập các ký tự" } }, .{ .kind = .twofa, .weak = false, .urlz = &.{ "/two_step_verification", "/two_factor", "/login/approvals" }, .text = &.{ "two-factor authentication required", "enter the code we sent", "enter the 6-digit code", "mã xác thực", "nhập mã gồm 6 chữ số" } }, .{ .kind = .blocked, .weak = false, .urlz = &.{}, .text = &.{ "action blocked", "you're temporarily blocked", "you have been temporarily blocked", "we limit how often you can post", "bạn tạm thời bị chặn", "hành động bị chặn" } }, .{ .kind = .warning, .weak = false, .urlz = &.{}, .text = &.{ "we noticed unusual activity", "unusual activity", "you can't use this feature right now", "hoạt động bất thường", "bạn không thể sử dụng tính năng này" } }, .{ .kind = .ratelimit, .weak = true, .urlz = &.{}, .text = &.{ "you're going too fast", "slow down", "try again later", "bạn thao tác quá nhanh", "thử lại sau" } }, .{ .kind = .logout, .weak = false, .urlz = &.{ "/login", "login.php", "/login/identify" }, .text = &.{ "log in to facebook", "log into facebook", "you must log in", "đăng nhập facebook", "bạn phải đăng nhập" } } };
pub fn check(urlz: []const u8, text: []const u8, dlg: []const u8) ?Halt { var ubuf: [512]u8 = undefined; var tbuf: [CF.scan * 2]u8 = undefined; var dbuf: [CF.scan * 2]u8 = undefined; const lurl = fld.fold(&ubuf, urlz[0..@min(urlz.len, ubuf.len / 2)]); const body = fld.fold(&tbuf, text[0..@min(text.len, CF.scan)]); const dial = fld.fold(&dbuf, dlg[0..@min(dlg.len, CF.scan)]); for (RULES) |rul| { if (fld.hasAny(lurl, rul.urlz)) return rul.kind; } for (RULES) |rul| { if (!rul.weak and fld.hasAny(body, rul.text)) return rul.kind; } for (RULES) |rul| { if (fld.hasAny(dial, rul.text)) return rul.kind; } return null; }
pub fn classOf(kind: Halt) Class { return switch (kind) { .checkpoint, .captcha, .twofa, .logout, .overlay => .needs, .warning, .blocked, .ratelimit => .unsafe }; }
pub fn name(kind: Halt) []const u8 { return @tagName(kind); }
pub fn isLogout(kind: Halt) bool { return kind == .logout; }
